import{_ as o,o as t,c as r,a2 as a}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Ceph Science User Group May 2025","description":"","frontmatter":{"title":"Ceph Science User Group May 2025","date":"2025-07-30T00:00:00.000Z","updated":"2025-07-30T00:00:00.000Z","tags":["Ceph","分布式存储","性能分析","硬件采购","Cephadm"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Ceph_Science_User_Group_May_2025.md","filePath":"posts/2025/Ceph_Science_User_Group_May_2025.md","lastUpdated":1780459816000}'),s={name:"posts/2025/Ceph_Science_User_Group_May_2025.md"};function i(n,e,l,p,c,_){return t(),r("div",null,[...e[0]||(e[0]=[a('<p>Ceph Science User Group 于 2023 年 5 月举行，会议涵盖了多个重要议题，以下是对会议内容的总结：</p><h3 id="主题演讲-ceph-在大规模高吞吐计算环境中的性能分析" tabindex="-1">主题演讲：Ceph 在大规模高吞吐计算环境中的性能分析 <a class="header-anchor" href="#主题演讲-ceph-在大规模高吞吐计算环境中的性能分析" aria-label="Permalink to &quot;主题演讲：Ceph 在大规模高吞吐计算环境中的性能分析&quot;">​</a></h3><p>演讲者 Tom（STFC）分享了 STFC 运行的 Ceph 集群 Echo 的性能分析结果。Echo 集群规模超过 100PB，主要为 LHC 实验提供存储支持。Tom 评估了将 RocksDB 从 HDD 迁移至 SSD 对性能的影响，发现：</p><ul><li><strong>Backfill 性能</strong>：Hybrid OSD（使用 SSD 存储 RocksDB）的延迟显著降低，HDD 吞吐可达 200-250MB/s。HDD-only OSD 在延迟低于 100MB/s 时性能波动大。</li><li><strong>写入操作</strong>：Hybrid 配置下，HDD 的 IOPS 需求降低，写入更稳定。</li><li><strong>读取操作</strong>：RocksDB 位置对读取性能影响微乎其微，推测因数据缓存在内存中。</li></ul><h3 id="讨论议题" tabindex="-1">讨论议题 <a class="header-anchor" href="#讨论议题" aria-label="Permalink to &quot;讨论议题&quot;">​</a></h3><ol><li><strong>Ceph RBD 故障排查</strong>：讨论了 RBD 节点因内核 Bug 进入“半死”状态的问题，提出了避免 Mon 与 OSD 共置等临时方案。</li><li><strong>Cephadm vs 手动部署</strong>：讨论了 Cephadm 和手动部署的优缺点，包括快速服务部署、解耦 OS 依赖、声明式 YAML 管理、黑盒操作、性能争议等。</li><li><strong>Quincy 17.2.9 紧急发布</strong>：分享了 BlueFS 的 LSN 问题导致的 OSD 崩溃的修复内容，建议高风险集群尽快更新。</li></ol><h3 id="行动计划" tabindex="-1">行动计划 <a class="header-anchor" href="#行动计划" aria-label="Permalink to &quot;行动计划&quot;">​</a></h3><ol><li><strong>硬件采购</strong>：Tom 将评估 SSD 对写入密集型场景的价值，提交成本效益分析。</li><li><strong>故障改进</strong>：Matteo 计划升级内核并测试分离 Mon/OSD 部署。</li><li><strong>Cephadm 优化</strong>：社区建议增强任务队列可视化。</li><li><strong>文档协作</strong>：建立 GitHub 仓库归档会议幻灯片。</li></ol><p>会议强调了 Ceph 在大规模高吞吐计算环境中的性能和稳定性，讨论了不同的部署和管理方案，并制定了后续的行动计划。</p>',9)])])}const S=o(s,[["render",i]]);export{d as __pageData,S as default};
